fn test_prime(n: u64) -> bool {
    // Handle small cases and evens
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }

    // Known bases that make Miller–Rabin deterministic for 64-bit integers
    const BASES: [u64; 7] = [2, 325, 9375, 28178, 450775, 9780504, 1795265022];

    // write n - 1 as d * 2^s with d odd
    let (s, d) = {
        let mut d = n - 1;
        let mut s = 0;
        while d & 1 == 0 {
            d >>= 1;
            s += 1;
        }
        (s, d)
    };

    // modular exponentiation: compute a^e mod m
    fn mod_pow(mut a: u64, mut e: u64, m: u64) -> u64 {
        let mut res = 1u64;
        a %= m;
        while e > 0 {
            if (e & 1) == 1 {
                res = mul_mod(res, a, m);
            }
            a = mul_mod(a, a, m);
            e >>= 1;
        }
        res
    }

    // safe modular multiply to avoid overflow
    fn mul_mod(a: u64, b: u64, m: u64) -> u64 {
        ((a as u128 * b as u128) % (m as u128)) as u64
    }

    // perform the Miller–Rabin check for a single base
    fn miller_rabin_check(a: u64, s: u32, d: u64, n: u64) -> bool {
        let mut x = mod_pow(a, d, n);
        if x == 1 || x == n - 1 {
            return true;
        }
        for _ in 1..s {
            x = mul_mod(x, x, n);
            if x == n - 1 {
                return true;
            }
        }
        false
    }

    // test all bases
    for &a in &BASES {
        // skip a if it's >= n
        let a = if a % n == 0 { continue; } else { a };
        if !miller_rabin_check(a, s, d, n) {
            return false;
        }
    }

    true
}

